$slug=$_GET['page']??'index';if(!preg_match('/^[a-z0-9-]+$/D',$slug))$slug='404';
function post_card(array $p,bool $featured=false): string{
    $book=$p['type']==='book';return '<article class="card '.($book?'book-summary-card':(str_contains($p['image'],'london')?'photo-card':'museum-card')).'" data-category="'.h($p['category']).'"'.($book?' data-book-group="'.h($p['category']).'" data-bestseller="'.(in_array($p['slug'],['atomic-habits', 'educated', 'the-midnight-library', 'project-hail-mary', 'the-martian', 'lessons-in-chemistry', 'where-the-crawdads-sing', 'the-silent-patient', 'the-seven-husbands-of-evelyn-hugo', 'thinking-fast-and-slow', 'outlive', 'becoming', 'born-a-crime', 'shoe-dog', 'the-creative-act', 'the-anxious-generation', 'brief-answers-to-the-big-questions', 'dare-to-lead', 'digital-minimalism', 'factfulness'],true)?'true':'false').'"':'').'"><a class="card-image" href="'.h($p['slug']).'.html">'.picture($p['image'],$book?'Cover of '.$p['title']:$p['title'],false,$featured?'(max-width: 850px) calc(100vw - 48px), 65vw':'').'</a><div class="card-content"><p class="eyebrow">'.h($book?$p['author']:$p['category']).'</p><h3><a href="'.h($p['slug']).'.html">'.h($p['title']).'</a></h3><p class="summary">'.h($p['subtitle']).'</p><p class="meta">'.h($p['published_at']).'</p></div></article>';
}
function cards(array $rows,bool $books=false): string{return '<div class="card-grid '.($books?'bookshelf-grid':'').'">'.implode('',array_map('post_card',$rows)).'</div>';}
function book_carousel():string{
    $rows=public_posts('book');if(!$rows&&blog_language()==='ar')return arabic_books_empty();return '<div class="book-carousel" data-book-carousel aria-label="The complete bookshelf"><div class="book-carousel-toolbar"><p>Every book, a different world.</p><button type="button" data-book-carousel-toggle aria-pressed="false" hidden>Pause scrolling</button></div><div class="book-carousel-viewport" data-book-viewport tabindex="0" aria-label="Book summaries. Scroll horizontally to explore."><div class="book-carousel-track"><div class="book-carousel-group">'.implode('',array_map('post_card',$rows)).'</div></div></div><p class="book-carousel-hint">Swipe or scroll to explore · Choose a book to read its summary</p></div>';
}
function gallery_html(int $limit=0): string{
    $rows=q('SELECT * FROM aa_gallery ORDER BY sort_order,id')->fetchAll();if($limit)$rows=array_slice($rows,0,$limit);$s='<div class="gallery-grid '.($limit?'home-gallery':'illustration-gallery').'">';
    foreach($rows as $i=>$raw){$g=localized_gallery_row($raw);$s.='<figure class="gallery-item" data-category="'.h($g['category']).'"><a class="gallery-open" data-photo="'.h(preg_replace('/-(1600|640)\.webp$/','',basename($g['image']))).'" href="'.h($g['image']).'" data-title="'.h($g['title']).'" data-alt="'.h($g['alt']).'" aria-label="Open image: '.h($g['title']).'">'.picture($g['image'],$g['alt']).'<span class="gallery-hover">View image ↗</span></a><figcaption><small>'.($i+1).' / '.h($g['category']).'</small><span>'.h($g['title']).'</span><p>'.(in_array(basename($g['image']),['london-green-1600.webp', 'london-winter-1600.webp', 'photo-flight-1600.webp', 'photo-london-street-1600.webp', 'photo-night-lights-1600.webp', 'photo-footsteps-1600.webp', 'london-lake-1600.webp', 'photo-gates-1600.webp', 'photo-company-1600.webp', 'photo-guest-1600.webp'],true)?'London trip · December 2025':'Photograph supplied by Ahmad').'</p></figcaption></figure>';
    }return $s.'</div>';
}
function viewer(): string{return '<dialog class="photo-viewer" aria-label="Gallery viewer"><div class="viewer-bar"><span class="viewer-count" aria-live="polite"></span><button type="button" data-viewer-close>Close ✕</button></div><div class="viewer-stage"><button class="viewer-prev" type="button" data-viewer-prev aria-label="Previous image">←</button><img class="viewer-image" alt=""><button class="viewer-next" type="button" data-viewer-next aria-label="Next image">→</button></div><div class="viewer-caption"><h2></h2><span>← → to explore · Esc to close</span></div></dialog>';}
function subscribe_block(): string{return '<section class="newsletter" id="newsletter"><div class="wrap newsletter-inner"><div><p class="eyebrow">Stay updated</p><h2>A note, now and then.</h2><p>'.h(local_setting('newsletter_intro','New ideas, reading notes, and things worth sharing.')).'</p></div><form class="newsletter-form" method="post" action="api/subscribe.php"><label for="newsletter-email">Email address</label><div class="input-row"><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="Your email address" required><button>Subscribe</button></div><label class="newsletter-consent"><input type="checkbox" name="consent" value="1" required> I want occasional blog updates by email.</label><input class="form-trap" name="website" tabindex="-1" autocomplete="off" aria-hidden="true"><p class="form-note">Your signup is saved privately. Unsubscribe using the link in future updates. <a href="privacy.html">Privacy</a></p></form></div></section>';}
function mast(string $label,string $title,string $intro): string{return '<section class="page-masthead"><div class="wrap"><p class="eyebrow">'.h($label).'</p><h1>'.h($title).'</h1><p class="dek">'.h($intro).'</p></div></section>';}
