    $main.='<section class="section wrap" id="articles"><div class="section-head"><div><p class="eyebrow">From the notebook</p><h2>Latest articles.</h2></div><a class="text-link" href="articles.html">Browse all articles</a></div>'.cards(array_slice(array_values(array_filter(public_posts('article'),fn($p)=>!$featured||$p['id']!==$featured['id'])),0,6)).'</section>';
    $main.='<section class="section reading-section" id="reading"><div class="wrap"><div class="section-head"><div><p class="eyebrow">From the bookshelf</p><h2>Good books. Lasting ideas.</h2></div><a class="text-link" href="book-summaries.html">Explore the bookshelf</a></div><div class="reading-feature"><div class="reading-photo pixel-reading">'.($pixel[0]??'').'</div><div class="reading-feature-copy"><p class="eyebrow">A reader’s notebook</p><h2>What stays after the last page.</h2><p>The ideas I take from books, the questions they leave behind, and how they shape my thinking.</p></div></div>'.book_carousel().'</div></section>';
