    $main.='<section class="section about-wash"><div class="wrap about-section"><div><span class="about-monogram" aria-hidden="true">Aa<span></span></span><p class="eyebrow">About Ahmad</p><h2>'.h(local_setting('about_title')).'</h2></div><div><p class="lead">'.h(local_setting('hero_intro')).'</p><a class="text-link" href="about.html">More about me</a></div></div></section>'.subscribe_block().viewer();
